import { execution } from '@dynatrace-sdk/automation-utils';

export default async function ({ executionId }) {
  const ex = await execution(executionId);
  const ev = ex.event() || {};
  const problemId =
    ev["display_id"] ||
    ev["problem.id"] ||
    ev["event.id"] ||
    ev.pid ||
    "unknown-problem";
  return {
    problemId,
    dedupKey: "dt-problem-" + problemId
  };
}

import { execution } from '@dynatrace-sdk/automation-utils';

export default async function ({ executionId }) {
  const ex = await execution(executionId);
  const p = await ex.result("prepare-close-ids");

  const routingKey = "__PD_ROUTING_KEY__";

  const body = {
    routing_key: routingKey,
    event_action: "resolve",
    dedup_key: p.dedupKey
  };

  const res = await fetch("https://events.pagerduty.com/v2/enqueue", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body)
  });
  const text = await res.text();
  let json = {};
  try { json = JSON.parse(text); } catch (e) { json = { raw: text }; }
  if (!res.ok) {
    throw new Error("PagerDuty resolve failed HTTP " + res.status + ": " + text);
  }
  return {
    status: json.status,
    dedupKey: json.dedup_key || p.dedupKey,
    message: json.message,
    raw: json
  };
}
